[{"path": "../shared/cases/401.txt", "field": "incorrect_code", "line_start": 1, "line_end": 29, "quote": "def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    if a >= 100:
        return False

    prime_factors = []
    for i in range(2, a):
        if is_prime(i) and a % i == 0:
            prime_factors.append(i)
            a = a // i
            if len(prime_factors) == 3 and a == 1:
                return True
            if len(prime_factors) > 3:
                return False
    return False", "sha256": "d15ab6968ba82c011a9bd87f1f391c60ffb41e2495b89a5bbefc91b3f2a06cc9"}]

[{"path": "../shared/cases/51.txt", "field": "incorrect_code", "line_start": 1, "line_end": 20, "quote": "def prime_length(string):
    """Write a function that takes a string and returns True if the string
    length is a prime number or False otherwise
    Examples
    prime_length('Hello') == True
    prime_length('abcdcba') == True
    prime_length('kittens') == True
    prime_length('orange') == False
    """
    if len(string) == 1:
        return True
    elif len(string) == 2:
        return True
    elif len(string) % 2 == 0:
        return False
    else:
        for i in range(3, int(len(string) / 2) + 1, 2):
            if len(string) % i == 0:
                return False
        return True", "sha256": "734b7061f005298b8af54f1fa1c6332143987cd7f06078b08c454c412f02eb2e"}]

