[{"path": "../shared/cases/415.txt", "field": "incorrect_code", "line_start": 1, "line_end": 23, "quote": "def minPath(grid, k):
    def neighbors(r, c):
        for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                yield nr, nc

    def dfs(r, c, path, k):
        if k == 0:
            return path
        min_path = path + [float('inf')] * k
        for nr, nc in neighbors(r, c):
